#pragma GCC optimize(3)
#include <bits/stdc++.h>
#define MAX_SIZE 7100
typedef long long ll;
#define INF 1000000000
using namespace std;

struct FlowSolver {
    struct Edge {
        int from, to;
        ll flow, capacity;
    };
    int s, t;
    vector<Edge> edges;
    vector<int> adj[MAX_SIZE];
    int dist[MAX_SIZE], visited[MAX_SIZE], current[MAX_SIZE];

    void reset() {
        edges.clear();
        for (int i = 0; i < MAX_SIZE; i++) {
            adj[i].clear();
        }
    }

    void addEdge(int u, int v, ll cap) {
        Edge e1 = {u, v, 0LL, cap};
        Edge e2 = {v, u, 0LL, 0};
        edges.push_back(e1);
        edges.push_back(e2);
        adj[u].push_back((int)edges.size() - 2);
        adj[v].push_back((int)edges.size() - 1);
    }

    bool buildLevelGraph() {
        memset(visited, 0, sizeof(visited));
        memset(dist, 0, sizeof(dist));
        queue<int> q;
        q.push(s);
        visited[s] = 1;
        dist[s] = 0;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int i : adj[v]) {
                Edge &e = edges[i];
                int u = e.to;
                if (!visited[u] && e.capacity > e.flow) {
                    dist[u] = dist[v] + 1;
                    q.push(u);
                    visited[u] = 1;
                }
            }
        }
        return visited[t];
    }

    ll sendFlow(int v, ll flow) {
        if (v == t || flow == 0) return flow;
        ll total = 0;
        for (int &i = current[v]; i < (int)adj[v].size(); i++) {
            Edge &e = edges[adj[v][i]];
            if (dist[v] + 1 == dist[e.to]) {
                ll pushed = sendFlow(e.to, min(flow, e.capacity - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[adj[v][i] ^ 1].flow -= pushed;
                    total += pushed;
                    flow -= pushed;
                    if (flow == 0) break;
                }
            }
        }
        return total;
    }

    ll maxFlow() {
        ll totalFlow = 0;
        while (buildLevelGraph()) {
            for (int i = 0; i < MAX_SIZE; i++) current[i] = 0;
            totalFlow += sendFlow(s, INF);
        }
        return totalFlow;
    }
};

FlowSolver solver;
char mazeA[14][14], mazeB[14][14];
bool visitedMap[14][14];
int distMap[14][14];
int sizeN;
int targetNodes[103];

void BFS(int x, int y) {
    std::queue<std::pair<std::pair<int, int>, int>> q;
    for (int i = 0; i < 14; i++) {
        for (int j = 0; j < 14; j++) {
            distMap[i][j] = 111;
        }
    }
    distMap[x][y] = 0;
    q.push({{x, y}, 0});
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        int cx = p.first.first, cy = p.first.second, d = p.second;
        if (visitedMap[cx][cy]) continue;
        visitedMap[cx][cy] = true;
        distMap[cx][cy] = d;
        for (int i = 0; i < 4; i++) {
            int tx = cx + dx[i], ty = cy + dy[i];
            if (tx <= 0 || tx > sizeN || ty <= 0 || ty > sizeN || visitedMap[tx][ty] || mazeA[tx][ty] == 'Y') continue;
            q.push({{tx, ty}, d + 1});
        }
    }
}

int get_idx(int level, int x, int y) {
    return level * sizeN * sizeN + (x - 1) * sizeN + y;
}

int main() {
    int i, t, j, k;
    scanf("%d%d", &sizeN, &t);
    for (i = 1; i <= sizeN; i++) scanf("%s", mazeA[i] + 1);
    for (i = 1; i <= sizeN; i++) scanf("%s", mazeB[i] + 1);
    solver.s = 0; solver.t = MAX_SIZE - 2;
    int zx = 0, zy = 0;
    for (i = 1; i <= sizeN; i++) {
        for (j = 1; j <= sizeN; j++) {
            if (mazeA[i][j] == 'Z') {
                zx = i; zy = j; break;
            }
        }
    }
    for (i = 1; i <= sizeN * sizeN; i++) targetNodes[i] = MAX_SIZE - 3 - (sizeN * sizeN - i);
    BFS(zx, zy);
    for (i = 1; i <= sizeN; i++) {
        for (j = 1; j <= sizeN; j++) {
            if (mazeA[i][j] >= '0' && mazeA[i][j] <= '9')
                solver.addEdge(solver.s, get_idx(0, i, j), mazeA[i][j] - '0');
            if (mazeB[i][j] >= '0' && mazeB[i][j] <= '9')
                solver.addEdge(targetNodes[get_idx(0, i, j)], solver.t, mazeB[i][j] - '0');
            solver.addEdge(get_idx(0, i, j), targetNodes[get_idx(0, i, j)], INF);
        }
    }
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    for (i = 1; i <= t; i++) {
        for (j = 1; j <= sizeN; j++) {
            for (k = 1; k <= sizeN; k++) {
                if (mazeA[j][k] == 'Y' || mazeA[j][k] == 'Z') continue;
                for (int l = 0; l < 4; l++) {
                    int tx = j + dx[l], ty = k + dy[l];
                    if (tx >= 1 && tx <= sizeN && ty >= 1 && ty <= sizeN && mazeA[tx][ty] != 'Y' && mazeA[tx][ty] != 'Z') {
                        if (distMap[j][k] >= i && distMap[tx][ty] >= i) {
                            solver.addEdge(get_idx(i - 1, tx, ty), get_idx(i, j, k), INF);
                        }
                    }
                }
                solver.addEdge(get_idx(i, j, k), targetNodes[get_idx(0, j, k)], INF);
            }
        }
    }
    printf("%lld\n", solver.maxFlow());
    return 0;
}
